/** Bounded uncompressed ZIP writer. Entry paths are generated by the server, never user paths. */
const crcTable=Array.from({length:256},(_,n)=>{let c=n;for(let i=0;i<8;i++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;});
function crc32(bytes:Uint8Array){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
export function makeAuditZip(entries:Array<{name:string;bytes:Uint8Array}>){if(entries.length>51||entries.reduce((n,e)=>n+e.bytes.length,0)>32*1024*1024)throw new Error("Archive limit exceeded");const names=new Set<string>(),parts:Buffer[]=[],central:Buffer[]=[];let offset=0;for(const e of entries){if(!/^[a-zA-Z0-9_.-]{1,180}$/.test(e.name)||e.name.includes("..")||names.has(e.name))throw new Error("Unsafe archive name");names.add(e.name);const name=Buffer.from(e.name),data=Buffer.from(e.bytes),crc=crc32(data),h=Buffer.alloc(30);h.writeUInt32LE(0x04034b50);h.writeUInt16LE(20,4);h.writeUInt16LE(0x800,6);h.writeUInt16LE(33,12);h.writeUInt32LE(crc,14);h.writeUInt32LE(data.length,18);h.writeUInt32LE(data.length,22);h.writeUInt16LE(name.length,26);parts.push(h,name,data);const c=Buffer.alloc(46);c.writeUInt32LE(0x02014b50);c.writeUInt16LE(20,4);c.writeUInt16LE(20,6);c.writeUInt16LE(0x800,8);c.writeUInt16LE(33,14);c.writeUInt32LE(crc,16);c.writeUInt32LE(data.length,20);c.writeUInt32LE(data.length,24);c.writeUInt16LE(name.length,28);c.writeUInt32LE(offset,42);central.push(c,name);offset+=h.length+name.length+data.length;}const centralBytes=Buffer.concat(central),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(entries.length,8);end.writeUInt16LE(entries.length,10);end.writeUInt32LE(centralBytes.length,12);end.writeUInt32LE(offset,16);return Buffer.concat([...parts,centralBytes,end]);}
export function archiveFilename(index:number,name:string){const clean=name.replace(/[^a-zA-Z0-9_.-]/g,"_").replace(/\.{2,}/g,"_").slice(-140)||"evidence";return String(index+1).padStart(3,"0")+"-"+clean;}
